def verifier(assign):
    # Recompute x, y, verify the identity at high precision, and return the minimal k.
    from fractions import Fraction
    import math

    # Helper: real cube root
    def cbrt(z):
        return math.copysign(abs(z) ** (1.0/3.0), z)

    # Extract required parameters
    try:
        P = int(assign['p_coeff'])
        Q = int(assign['q_coeff'])
        r = int(assign['r_const'])
        r0 = int(assign['r0_const'])
        c_num = int(assign['c_num'])
        c_den = int(assign['c_den'])
        s_num = int(assign['s_num'])
        s_den = int(assign['s_den'])
        g0 = int(assign['g0'])
        g1 = int(assign['g1'])
    except Exception:
        # Missing or invalid fields
        return (False, None)

    # Parse fractional coefficients a0,a1,a2
    def parse_frac(val):
        if isinstance(val, (int, float)):
            return Fraction(val).limit_denominator()
        s = str(val)
        if '/' in s:
            num, den = s.split('/')
            return Fraction(int(num), int(den))
        return Fraction(int(s), 1)
    try:
        a0 = parse_frac(assign['a0'])
        a1 = parse_frac(assign['a1'])
        a2 = parse_frac(assign['a2'])
    except Exception:
        return (False, None)

    C = Fraction(c_num, c_den)
    s = Fraction(s_num, s_den)
    # Compute t, x, y
    t = Fraction(g0 * s_den + g1 * s_num - Q * s_den, 2 * s_den)
    x = (Fraction(1,1) - s*s) / P
    y = (Fraction(1,1) - t*t) / Q

    # Domain checks
    if not (x > 0 and y > 0):
        return (False, None)
    if not ((Fraction(1,1) - P * x) > 0 and (Fraction(1,1) - Q * y) > 0):
        return (False, None)

    # Evaluate the identity numerically
    def to_float(fr):
        return float(fr.numerator) / float(fr.denominator)
    s_f = math.sqrt(max(0.0, 1.0 - P * to_float(x)))
    # s_f should match sqrt(1 - P x)
    t_f = math.sqrt(max(0.0, 1.0 - Q * to_float(y)))
    # According to construction, t_f should equal float(t), but we rely only on equation

    # Build D and cube-root arguments
    D = Fraction(r**3, 1) + Fraction(3*r,1) * C * x*x
    D_f = to_float(D)
    c3x6_f = to_float(C**3 * x**6)
    sqrt_term = math.sqrt((D_f/2.0)**2 + c3x6_f)
    c1 = cbrt(D_f/2.0 + sqrt_term)
    c2 = cbrt(D_f/2.0 - sqrt_term)

    # Fractional term: a0 + a1 * sqrt(1 - P x) + a2 * (1 - P x)
    frac_val = a0 + a1 * (Fraction(1,1) - P * x).sqrt() if False else None
    # We can't do exact sqrt with Fraction; evaluate using float consistently.
    frac_f = to_float(a0) + to_float(a1) * s_f + to_float(a2) * (1.0 - P * to_float(x))

    lhs = r0 + t_f
    rhs = to_float(y) + frac_f + c1 + c2
    if not (math.isfinite(lhs) and math.isfinite(rhs)):
        return (False, None)
    if abs(lhs - rhs) > 1e-7:
        # Numerical mismatch: invalid assignment
        return (False, None)

    # Compute minimal k as lcm of denominators of x and y
    def lcm(a,b):
        return a // math.gcd(a,b) * b
    k = lcm(x.denominator, y.denominator)

    # Difficulty enforcement: ensure non-trivial denominators
    if k < 1000:
        return (False, None)
    if x.numerator == 0 or y.numerator == 0:
        return (False, None)

    answer = f"### The final answer is: $\\boxed{{{k}}}$"
    return (True, answer)
